/**
 * FreeLang Nexus - @call c:lib 실제 실행 테스트
 *
 * 실제 gcc + 라이브러리 링크 + 실행까지 검증
 * @call c:m      → -lm   (수학)
 * @call c:sqlite3 → -lsqlite3
 * @call c:curl    → -lcurl
 */

import { NexusLexer } from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';
import { NexusRunner } from '../src/nexus/runtime/nexus-runner';

function compileAndRun(flCode: string): { output: string; errors: string[]; linkFlags: string[] } {
  const tokens = new NexusLexer(flCode).tokenize();
  const ast = new NexusParser(tokens).parse();
  const codegen = new NexusCodegen();
  const result = codegen.generateProgram(ast);
  const runner = new NexusRunner();
  const run = runner.run(result);
  return {
    output: run.cOutput,
    errors: run.errors,
    linkFlags: result.linkFlags,
  };
}

// ─── linkFlags 수집 검증 ──────────────────────────────────────────────────────

describe('@call c:lib - linkFlags 수집', () => {
  test('Test 1: @call c:sqlite3 → -lsqlite3 수집', () => {
    const tokens = new NexusLexer('@mode(v)\n@call c:sqlite3\n').tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = new NexusCodegen().generate(ast);
    expect(result.linkFlags).toContain('-lsqlite3');
  });

  test('Test 2: @call c:m → -lm 수집', () => {
    const tokens = new NexusLexer('@mode(v)\n@call c:m\n').tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = new NexusCodegen().generate(ast);
    expect(result.linkFlags).toContain('-lm');
  });

  test('Test 3: @call c:curl → -lcurl 수집', () => {
    const tokens = new NexusLexer('@mode(v)\n@call c:curl\n').tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = new NexusCodegen().generate(ast);
    expect(result.linkFlags).toContain('-lcurl');
  });

  test('Test 4: 여러 @call → linkFlags 중복 없이 합산', () => {
    const tokens = new NexusLexer('@mode(v)\n@call c:sqlite3\n@call c:m\n@call c:m\n').tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = new NexusCodegen().generate(ast);
    // -lm은 중복 없이 1개
    expect(result.linkFlags.filter(f => f === '-lm').length).toBe(1);
    expect(result.linkFlags).toContain('-lsqlite3');
  });

