/**
 * FreeLang Nexus - @lang 블록 E2E 실행 테스트
 *
 * @lang("c")   → gcc로 .so 빌드 → FreeLang main에서 호출
 * @lang("rust") → rustc로 .so 빌드 → FreeLang main에서 호출
 * @lang("cpp")  → clang++로 .so 빌드 → FreeLang main에서 호출
 *
 * 환경이 없으면 자동 skip
 */

import { execSync } from 'child_process';
import { NexusLexer }   from '../src/nexus/lexer/nexus-lexer';
import { NexusParser }  from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';
import { NexusRunner }  from '../src/nexus/runtime/nexus-runner';

// ─── 환경 감지 ──────────────────────────────────────────────────────────────

function hasGcc(): boolean {
  try { execSync('gcc --version', { stdio: 'pipe' }); return true; } catch { return false; }
}
function hasClang(): boolean {
  try { execSync('clang --version', { stdio: 'pipe' }); return true; } catch { return false; }
}
function hasRustc(): boolean {
  try { execSync('rustc --version', { stdio: 'pipe' }); return true; } catch { return false; }
}

// ─── 헬퍼 ──────────────────────────────────────────────────────────────────

function run(code: string): { output: string; errors: string[] } {
  const tokens = new NexusLexer(code).tokenize();
  const ast    = new NexusParser(tokens).parse();
  const result = new NexusCodegen().generateProgram(ast);
  const runner = new NexusRunner();
  const out    = runner.run(result);
  return { output: out.cOutput, errors: out.errors };
}

// ─── @lang("c") E2E ─────────────────────────────────────────────────────────

describe('@lang("c") E2E - C 소스 빌드 + 실행', () => {

  (hasGcc() || hasClang() ? test : test.skip)(
    'LE2E-1: @lang("c") add 함수 → FreeLang에서 호출 → 출력 확인',
    () => {
      const code = `
@mode(v)
@lang("c")
@artifact("libcadd.so")
@compile("gcc -shared -fPIC -o libcadd.so cadd.c")
---
int cadd(int a, int b) { return a + b; }
---

fn cadd(a: i64, b: i64) -> i64

fn main() -> i64 {
  let r = cadd(10, 20)
  println(r)
  return 0
}
`;
      const { output, errors } = run(code);
      expect(errors).toHaveLength(0);
      expect(output.trim()).toBe('30');
    }
  );

  (hasGcc() || hasClang() ? test : test.skip)(
    'LE2E-2: @lang("c") 문자열 반환 함수 → println 출력',
    () => {
      const code = `
@mode(v)
@lang("c")
@artifact("libhello.so")
@compile("gcc -shared -fPIC -o libhello.so hello.c")
---
#include <string.h>
void greet(char *buf) { strcpy(buf, "hello from C"); }
---

fn greet(buf: string) -> void

fn main() -> i64 {
  println("C FFI OK")
  return 0
}
`;
      const { output, errors } = run(code);
      expect(errors).toHaveLength(0);
      expect(output.trim()).toBe('C FFI OK');
    }
  );

  (hasGcc() || hasClang() ? test : test.skip)(
    'LE2E-3: @lang("c") 연산 체인 → 결과 누산',
    () => {
      const code = `
@mode(v)
@lang("c")
@artifact("libmath2.so")
@compile("gcc -shared -fPIC -o libmath2.so math2.c")
---
int multiply(int a, int b) { return a * b; }
int subtract(int a, int b) { return a - b; }
---

fn multiply(a: i64, b: i64) -> i64
fn subtract(a: i64, b: i64) -> i64

fn main() -> i64 {
  let a = multiply(6, 7)
  let b = subtract(a, 2)
  println(b)
  return 0
}
`;
      const { output, errors } = run(code);
      expect(errors).toHaveLength(0);
      expect(output.trim()).toBe('40');
    }
  );

});

// ─── @lang("rust") E2E ───────────────────────────────────────────────────────

describe('@lang("rust") E2E - Rust 소스 빌드 + 실행', () => {

  (hasRustc() ? test : test.skip)(
    'LE2E-4: @lang("rust") add 함수 → FreeLang에서 호출',
    () => {
      const code = `
@mode(v)
@lang("rust")
@artifact("librust_add.so")
@compile("rustc --crate-type cdylib -o librust_add.so rust_add.rs")
---
#[no_mangle]
pub extern "C" fn rust_add(a: i64, b: i64) -> i64 {
    a + b
}
---

fn rust_add(a: i64, b: i64) -> i64

fn main() -> i64 {
  let r = rust_add(100, 23)
  println(r)
  return 0
}
`;
      const { output, errors } = run(code);
      expect(errors).toHaveLength(0);
      expect(output.trim()).toBe('123');
    }
  );

  (hasRustc() ? test : test.skip)(
    'LE2E-5: @lang("rust") multiply → 결과 검증',
    () => {
      const code = `
@mode(v)
@lang("rust")
@artifact("librust_mul.so")
@compile("rustc --crate-type cdylib -o librust_mul.so rust_mul.rs")
---
#[no_mangle]
pub extern "C" fn rust_mul(a: i64, b: i64) -> i64 {
    a * b
}
---

fn rust_mul(a: i64, b: i64) -> i64

fn main() -> i64 {
  let r = rust_mul(7, 8)
  println(r)
  return 0
}
`;
      const { output, errors } = run(code);
      expect(errors).toHaveLength(0);
      expect(output.trim()).toBe('56');
    }
  );

});

// ─── @lang("cpp") E2E ───────────────────────────────────────────────────────

describe('@lang("cpp") E2E - C++ 소스 빌드 + 실행', () => {

  (hasClang() ? test : test.skip)(
    'LE2E-6: @lang("cpp") extern "C" 함수 → FreeLang에서 호출',
    () => {
      const code = `
@mode(v)
@lang("cpp")
@artifact("libcpp_sum.so")
@compile("clang++ -shared -fPIC -o libcpp_sum.so cpp_sum.cpp")
---
extern "C" {
  int cpp_sum(int a, int b) { return a + b; }
}
---

fn cpp_sum(a: i64, b: i64) -> i64

fn main() -> i64 {
  let r = cpp_sum(55, 45)
  println(r)
  return 0
}
`;
      const { output, errors } = run(code);
      expect(errors).toHaveLength(0);
      expect(output.trim()).toBe('100');
    }
  );

});

// ─── @lang 코드젠 단위 검증 (컴파일러 불필요) ────────────────────────────────

describe('@lang 코드젠 단위 검증', () => {

  test('LE2E-7: @lang("c") → externLibs에 sourceCode 포함', () => {
    const code = `
@mode(v)
@lang("c")
@artifact("libfoo.so")
@compile("gcc -shared -fPIC -o libfoo.so foo.c")
---
int foo() { return 42; }
---
`;
    const tokens = new NexusLexer(code).tokenize();
    const ast    = new NexusParser(tokens).parse();
    const result = new NexusCodegen().generate(ast);

    expect(result.externLibs).toHaveLength(1);
    const lib = result.externLibs[0];
    expect(lib.lang).toBe('c');
    expect(lib.sourceCode).toContain('int foo()');
    expect(lib.artifact).toBe('libfoo.so');
    expect(lib.buildCmd).toContain('gcc');
  });

  test('LE2E-8: @lang("rust") → externLibs lang=rust, buildCmd 포함', () => {
    const code = `
@mode(v)
@lang("rust")
@artifact("libbar.so")
@compile("rustc --crate-type cdylib -o libbar.so bar.rs")
---
#[no_mangle]
pub extern "C" fn bar() -> i64 { 42 }
---
`;
    const tokens = new NexusLexer(code).tokenize();
    const ast    = new NexusParser(tokens).parse();
    const result = new NexusCodegen().generate(ast);

    expect(result.externLibs[0].lang).toBe('rust');
    expect(result.externLibs[0].buildCmd).toContain('rustc');
    expect(result.externLibs[0].sourceCode).toContain('#[no_mangle]');
  });

  test('LE2E-9: @lang 2개 혼합 → externLibs 2개', () => {
    const code = `
@mode(v)
@lang("c")
@artifact("liba.so")
@compile("gcc -shared -fPIC -o liba.so a.c")
---
int fa() { return 1; }
---

@lang("rust")
@artifact("libb.so")
@compile("rustc --crate-type cdylib -o libb.so b.rs")
---
#[no_mangle]
pub extern "C" fn fb() -> i64 { 2 }
---
`;
    const tokens = new NexusLexer(code).tokenize();
    const ast    = new NexusParser(tokens).parse();
    const result = new NexusCodegen().generate(ast);

    expect(result.externLibs).toHaveLength(2);
    expect(result.externLibs.map((l: any) => l.lang)).toEqual(['c', 'rust']);
  });

  test('LE2E-10: @lang("c") → C 코드에 extern 선언 포함', () => {
    const code = `
@mode(v)
@lang("c")
@artifact("libcalc.so")
@compile("gcc -shared -fPIC -o libcalc.so calc.c")
---
int calc_add(int a, int b) { return a + b; }
---
`;
    const tokens = new NexusLexer(code).tokenize();
    const ast    = new NexusParser(tokens).parse();
    const result = new NexusCodegen().generate(ast);

    // C 코드에 extern 선언 또는 include 힌트가 있어야 함
    expect(result.c).toBeTruthy();
  });

});

