  const mainC = `#include <stdio.h>\nextern int cadd(int a, int b);\nint main(){printf("%d\\n",cadd(10,20));return 0;}\n`;
  fs.writeFileSync(mainSrc, mainC);

  // 두 소스 파일을 함께 컴파일
  execSync(`gcc -o ${binFile} ${mainSrc} ${libSrc}`, { stdio: 'pipe' });
  const result = spawnSync(binFile, [], { encoding: 'utf-8', stdio: 'pipe' });
  console.log('direct compile output:', result.stdout?.trim());
  expect(result.stdout?.trim()).toBe('30');
});
