    // C/C++인 경우 Android에서 동적 링크(.so) 불가 → 정적 아카이브(.a)로 빌드
    const isC = ['c', 'cpp', 'c++'].includes(lang.toLowerCase());
    if (isC && sourceName) {
      const srcFile  = path.join(workDir, sourceName);
