/**
 * FreeLang Nexus - 정적 분석 Checker
 *
 * 감지 항목:
 *  - 미사용 변수 → warning
 *  - 반환 타입 선언 있는데 return 없음 → error
 */

import * as AST from '../parser/ast';

export interface CheckDiagnostic {
  severity: 'error' | 'warning';
  message: string;
  line: number;
  column: number;
}

export class NexusChecker {
  private diagnostics: CheckDiagnostic[] = [];

  check(ast: AST.Program): CheckDiagnostic[] {
    this.diagnostics = [];
    for (const node of ast.body) {
      if (node.type === 'VFunction' || node.type === 'PyFunction') {
        this.checkFunction(node as AST.VFunction | AST.PyFunction);
      }
    }
    return this.diagnostics;
  }

  // ─── 함수 수준 검사 ───────────────────────────────────────────────────────

  private checkFunction(fn: AST.VFunction | AST.PyFunction): void {
    // 미사용 변수 검사
    this.checkUnusedVars(fn);

    // 반환 타입 선언 있는데 return 없음 검사
    if (fn.returnType && fn.returnType !== 'void') {
      const hasReturn = this.bodyHasReturn(fn.body);
      if (!hasReturn) {
        this.error(
          `함수 '${fn.name}': 반환 타입 '${fn.returnType}' 선언이 있지만 return 문이 없습니다`,
          fn.line,
          fn.column
        );
      }
    }
  }

  // ─── 미사용 변수 ──────────────────────────────────────────────────────────

  private checkUnusedVars(fn: AST.VFunction | AST.PyFunction): void {
    // 선언된 let 변수 수집 (name → AssignStatement)
    const declared = new Map<string, AST.AssignStatement>();
    this.collectAssigns(fn.body, declared);

    // 파라미터 이름은 "사용된 것"으로 처리 (false positive 방지)
    const used = new Set<string>(fn.params.map((p) => p.name));

    // 사용된 식별자 수집 (let 선언 우변 + 모든 표현식)
    for (const stmt of fn.body) {
      this.collectUsedIdents(stmt, used, declared);
    }

    // 선언했지만 사용 안 한 변수 → warning
    for (const [name, node] of declared) {
      if (!used.has(name)) {
        this.warn(
          `미사용 변수: '${name}'`,
          node.line,
          node.column
        );
      }
    }
  }

  /** let 선언만 수집 (lhs 이름 → 노드) */
  private collectAssigns(
    stmts: AST.Statement[],
    out: Map<string, AST.AssignStatement>
  ): void {
    for (const stmt of stmts) {
      if (stmt.type === 'Assign') {
        out.set(stmt.name, stmt);
      }
      // 중첩 블록 탐색
      this.nestedBodies(stmt).forEach((b) => this.collectAssigns(b, out));
    }
  }

  /** 표현식/문장에서 사용된 식별자 수집 */
  private collectUsedIdents(
    stmt: AST.Statement,
    used: Set<string>,
    declared: Map<string, AST.AssignStatement>
  ): void {
    if (stmt.type === 'Assign') {
      // 우변만 탐색 (lhs 이름은 선언 카운트에서 제외)
      this.collectUsedInExpr(stmt.value, used);
    } else if (stmt.type === 'Return') {
      if (stmt.value) this.collectUsedInExpr(stmt.value, used);
    } else if (stmt.type === 'ExprStatement') {
      this.collectUsedInExpr(stmt.expression, used);
    } else if (stmt.type === 'IfStatement') {
      this.collectUsedInExpr(stmt.condition, used);
      stmt.thenBranch.forEach((s) => this.collectUsedIdents(s, used, declared));
      (stmt.elseBranch ?? []).forEach((s) => this.collectUsedIdents(s, used, declared));
    } else if (stmt.type === 'WhileStatement') {
      this.collectUsedInExpr(stmt.condition, used);
      stmt.body.forEach((s) => this.collectUsedIdents(s, used, declared));
    } else if (stmt.type === 'ForStatement') {
      this.collectUsedInExpr(stmt.iterable, used);
      stmt.body.forEach((s) => this.collectUsedIdents(s, used, declared));
    } else if (stmt.type === 'MatchStatement') {
      this.collectUsedInExpr(stmt.subject, used);
      stmt.arms.forEach((arm) =>
        arm.body.forEach((s) => this.collectUsedIdents(s, used, declared))
      );
    }
  }

  /** 표현식에서 Identifier 이름 수집 */
  private collectUsedInExpr(expr: AST.Expression, used: Set<string>): void {
    if (!expr) return;
    switch (expr.type) {
      case 'Identifier':
        used.add((expr as AST.Identifier).name);
        break;
      case 'BinaryExpr': {
        const b = expr as AST.BinaryExpr;
        this.collectUsedInExpr(b.left, used);
        this.collectUsedInExpr(b.right, used);
        break;
      }
      case 'Call': {
        const c = expr as AST.CallExpr;
        if (typeof c.callee !== 'string') {
          this.collectUsedInExpr(c.callee as AST.Expression, used);
        }
        c.args.forEach((a) => this.collectUsedInExpr(a, used));
        break;
      }
      case 'Array':
        (expr as AST.ArrayLiteral).elements.forEach((e) =>
          this.collectUsedInExpr(e, used)
        );
        break;
      case 'MemberExpr': {
        const m = expr as any;
        this.collectUsedInExpr(m.object, used);
        break;
      }
      case 'IndexExpr': {
        const i = expr as any;
        this.collectUsedInExpr(i.object, used);
        this.collectUsedInExpr(i.index, used);
        break;
      }
      case 'StructLiteral': {
        const sl = expr as any;
        sl.fields.forEach((f: any) => this.collectUsedInExpr(f.value, used));
        break;
      }
      case 'UnaryExpr': {
        this.collectUsedInExpr((expr as any).operand, used);
        break;
      }
      // Number, String, Boolean: 리터럴, 식별자 없음
    }
  }

  // ─── return 존재 여부 ─────────────────────────────────────────────────────

  /**
   * body에 return 문이 있는지 탐색 (중첩 if/else/match도 포함)
   * 조건부 return만 있어도 true로 처리 (false-positive 억제)
   */
  private bodyHasReturn(stmts: AST.Statement[]): boolean {
    for (const stmt of stmts) {
      if (stmt.type === 'Return') return true;
      if (stmt.type === 'IfStatement') {
        if (
          this.bodyHasReturn(stmt.thenBranch) ||
          this.bodyHasReturn(stmt.elseBranch ?? [])
        )
          return true;
      }
      if (stmt.type === 'WhileStatement' && this.bodyHasReturn(stmt.body))
        return true;
      if (stmt.type === 'ForStatement' && this.bodyHasReturn(stmt.body))
        return true;
      if (
        stmt.type === 'MatchStatement' &&
        stmt.arms.some((arm) => this.bodyHasReturn(arm.body))
      )
        return true;
    }
    return false;
  }

  // ─── 중첩 블록 헬퍼 ───────────────────────────────────────────────────────

  private nestedBodies(stmt: AST.Statement): AST.Statement[][] {
    if (stmt.type === 'IfStatement') {
      return [stmt.thenBranch, stmt.elseBranch ?? []];
    }
    if (stmt.type === 'WhileStatement') return [stmt.body];
    if (stmt.type === 'ForStatement') return [stmt.body];
    if (stmt.type === 'MatchStatement') return stmt.arms.map((a) => a.body);
    return [];
  }

  // ─── 진단 생성 헬퍼 ───────────────────────────────────────────────────────

  private error(message: string, line: number, column: number): void {
    this.diagnostics.push({ severity: 'error', message, line, column });
  }

  private warn(message: string, line: number, column: number): void {
    this.diagnostics.push({ severity: 'warning', message, line, column });
  }
}

