      stmt.body.forEach((s) => this.collectUsedIdents(s, used, declared));
    } else if (stmt.type === 'ForStatement') {
      this.collectUsedInExpr(stmt.iterable, used);
      stmt.body.forEach((s) => this.collectUsedIdents(s, used, declared));
    } else if (stmt.type === 'MatchStatement') {
      this.collectUsedInExpr(stmt.subject, used);
      stmt.arms.forEach((arm) =>
        arm.body.forEach((s) => this.collectUsedIdents(s, used, declared))
      );
    }
  }

  /** 표현식에서 Identifier 이름 수집 */
  private collectUsedInExpr(expr: AST.Expression, used: Set<string>): void {
    if (!expr) return;
    switch (expr.type) {
      case 'Identifier':
        used.add((expr as AST.Identifier).name);
        break;
      case 'BinaryExpr': {
        const b = expr as AST.BinaryExpr;
        this.collectUsedInExpr(b.left, used);
        this.collectUsedInExpr(b.right, used);
        break;
      }
      case 'Call': {
        const c = expr as AST.CallExpr;
        if (typeof c.callee !== 'string') {
          this.collectUsedInExpr(c.callee as AST.Expression, used);
        }
        c.args.forEach((a) => this.collectUsedInExpr(a, used));
        break;
      }
      case 'Array':
        (expr as AST.ArrayLiteral).elements.forEach((e) =>
          this.collectUsedInExpr(e, used)
        );
        break;
      case 'MemberExpr': {
        const m = expr as any;
        this.collectUsedInExpr(m.object, used);
        break;
      }
      case 'IndexExpr': {
        const i = expr as any;
        this.collectUsedInExpr(i.object, used);
        this.collectUsedInExpr(i.index, used);
        break;
      }
      case 'StructLiteral': {
        const sl = expr as any;
        sl.fields.forEach((f: any) => this.collectUsedInExpr(f.value, used));
        break;
      }
      case 'UnaryExpr': {
        this.collectUsedInExpr((expr as any).operand, used);
        break;
      }
      // Number, String, Boolean: 리터럴, 식별자 없음
    }
  }

  // ─── return 존재 여부 ─────────────────────────────────────────────────────

  /**
   * body에 return 문이 있는지 탐색 (중첩 if/else/match도 포함)
   * 조건부 return만 있어도 true로 처리 (false-positive 억제)
   */
  private bodyHasReturn(stmts: AST.Statement[]): boolean {
    for (const stmt of stmts) {
      if (stmt.type === 'Return') return true;
      if (stmt.type === 'IfStatement') {
        if (
          this.bodyHasReturn(stmt.thenBranch) ||
          this.bodyHasReturn(stmt.elseBranch ?? [])
        )
          return true;
      }
      if (stmt.type === 'WhileStatement' && this.bodyHasReturn(stmt.body))
        return true;
      if (stmt.type === 'ForStatement' && this.bodyHasReturn(stmt.body))
        return true;
      if (
        stmt.type === 'MatchStatement' &&
        stmt.arms.some((arm) => this.bodyHasReturn(arm.body))
      )
        return true;
    }
    return false;
  }

  // ─── 중첩 블록 헬퍼 ───────────────────────────────────────────────────────

  private nestedBodies(stmt: AST.Statement): AST.Statement[][] {
    if (stmt.type === 'IfStatement') {
      return [stmt.thenBranch, stmt.elseBranch ?? []];
    }
    if (stmt.type === 'WhileStatement') return [stmt.body];
    if (stmt.type === 'ForStatement') return [stmt.body];
    if (stmt.type === 'MatchStatement') return stmt.arms.map((a) => a.body);
    return [];
  }

  // ─── 진단 생성 헬퍼 ───────────────────────────────────────────────────────

  private error(message: string, line: number, column: number): void {
    this.diagnostics.push({ severity: 'error', message, line, column });
  }

  private warn(message: string, line: number, column: number): void {
    this.diagnostics.push({ severity: 'warning', message, line, column });
  }
}

