async function checkFile(filePath: string): Promise<void> {
  try {
    if (!fs.existsSync(filePath)) {
      console.error(`❌ 파일을 찾을 수 없음: ${filePath}`);
      process.exit(1);
    }

    const source = fs.readFileSync(filePath, 'utf-8');

    // Lexer
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // Parser
    const parser = new NexusParser(tokens, source);
    const ast = parser.parse();

    // Checker
    const { NexusChecker } = await import('./checker/nexus-checker');
    const checker = new NexusChecker();
    const diagnostics = checker.check(ast);

    const errors   = diagnostics.filter((d) => d.severity === 'error');
    const warnings = diagnostics.filter((d) => d.severity === 'warning');

    warnings.forEach((d) =>
      console.warn(`⚠️  [${d.line}:${d.column}] ${d.message}`)
    );
    errors.forEach((d) =>
      console.error(`❌ [${d.line}:${d.column}] ${d.message}`)
    );

    if (errors.length > 0) {
      process.exit(1);
    }

    const fnCount = ast.body.filter(
      (b: any) => b.type === 'VFunction' || b.type === 'PyFunction'
    ).length;
    console.log(`✅ 검사 통과 (함수 ${fnCount}개, 경고 ${warnings.length}개)`);
  } catch (e) {
    console.error(`❌ 오류: ${(e as Error).message}`);
    process.exit(1);
  }
}

