/**
 * FreeLang Nexus - NexusChecker 테스트
 *
 * CH-1~5: 미사용 변수 warning
 * CH-6~10: return 누락 error
 * CH-11~15: 정상 케이스 (진단 없음)
 */

import { NexusLexer }   from '../src/nexus/lexer/nexus-lexer';
import { NexusParser }  from '../src/nexus/parser/nexus-parser';
import { NexusChecker, CheckDiagnostic } from '../src/nexus/checker/nexus-checker';

function check(src: string): CheckDiagnostic[] {
  const tokens = new NexusLexer(src).tokenize();
  const ast    = new NexusParser(tokens, src).parse();
  return new NexusChecker().check(ast);
}

function warns(diags: CheckDiagnostic[]) {
  return diags.filter((d) => d.severity === 'warning');
}
function errors(diags: CheckDiagnostic[]) {
  return diags.filter((d) => d.severity === 'error');
}

// ─── 미사용 변수 ─────────────────────────────────────────────────────────────

describe('NexusChecker - 미사용 변수 warning', () => {

  test('CH-1: 단순 미사용 변수 → warning 1개', () => {
    const diags = check(`@mode(v)
fn main() -> i64 {
  let unused = 42
  return 0
}
`);
    expect(warns(diags)).toHaveLength(1);
    expect(warns(diags)[0].message).toContain('unused');
  });

  test('CH-2: 미사용 변수 2개 → warning 2개', () => {
    const diags = check(`@mode(v)
fn main() -> i64 {
  let a = 1
  let b = 2
  return 0
}
`);
    expect(warns(diags)).toHaveLength(2);
  });

  test('CH-3: 사용된 변수 → warning 없음', () => {
    const diags = check(`@mode(v)
fn main() -> i64 {
  let x = 10
  println(x)
  return 0
}
`);
    expect(warns(diags)).toHaveLength(0);
  });

  test('CH-4: 파라미터는 미사용 경고 제외', () => {
    const diags = check(`@mode(v)
fn add(a: i64, b: i64) -> i64 {
  return a + b
}
fn main() -> i64 { return 0 }
`);
    expect(warns(diags)).toHaveLength(0);
  });

  test('CH-5: 조건문 안에서 사용된 변수 → warning 없음', () => {
    const diags = check(`@mode(v)
fn main() -> i64 {
  let x = 5
  if x > 0 {
    println(x)
  }
  return 0
}
`);
    expect(warns(diags)).toHaveLength(0);
  });

});

// ─── return 누락 ─────────────────────────────────────────────────────────────

describe('NexusChecker - return 누락 error', () => {

  test('CH-6: return 없는 i64 반환 함수 → error 1개', () => {
    const diags = check(`@mode(v)
fn add(a: i64, b: i64) -> i64 {
  let c = a + b
}
fn main() -> i64 { return 0 }
`);
    expect(errors(diags)).toHaveLength(1);
    expect(errors(diags)[0].message).toContain('add');
    expect(errors(diags)[0].message).toContain('i64');
  });

  test('CH-7: return 있는 함수 → error 없음', () => {
    const diags = check(`@mode(v)
fn add(a: i64, b: i64) -> i64 {
  return a + b
}
fn main() -> i64 { return 0 }
`);
    expect(errors(diags)).toHaveLength(0);
  });

  test('CH-8: 반환 타입 없는 함수 → error 없음', () => {
    const diags = check(`@mode(v)
fn greet() {
  println("hi")
}
fn main() -> i64 { return 0 }
`);
    expect(errors(diags)).toHaveLength(0);
  });

  test('CH-9: if 블록 안 return → error 없음', () => {
    const diags = check(`@mode(v)
fn sign(n: i64) -> i64 {
  if n > 0 {
    return 1
  }
  return 0
}
fn main() -> i64 { return 0 }
`);
    expect(errors(diags)).toHaveLength(0);
  });

  test('CH-10: 여러 함수 중 하나만 return 없음 → error 1개', () => {
    const diags = check(`@mode(v)
fn ok() -> i64 {
  return 1
}
fn bad() -> i64 {
  let x = 1
}
fn main() -> i64 { return 0 }
`);
    expect(errors(diags)).toHaveLength(1);
    expect(errors(diags)[0].message).toContain('bad');
  });

});

// ─── 정상 케이스 ─────────────────────────────────────────────────────────────

describe('NexusChecker - 정상 케이스 (진단 없음)', () => {

  test('CH-11: 빈 main 함수 (return 있음)', () => {
    const diags = check(`@mode(v)
fn main() -> i64 {
  return 0
}
`);
    expect(diags).toHaveLength(0);
  });

  test('CH-12: struct 정의 + 사용 (struct는 변수 아님)', () => {
    const diags = check(`@mode(v)
struct Point { x: i64, y: i64 }
fn main() -> i64 {
  let p = Point { x: 1, y: 2 }
  println(p.x)
  return 0
}
`);
    expect(warns(diags)).toHaveLength(0);
  });

  test('CH-13: while 루프 내 변수 사용', () => {
    const diags = check(`@mode(v)
fn main() -> i64 {
  let i = 0
  while i < 10 {
    i = i + 1
  }
  return 0
}
`);
    expect(warns(diags)).toHaveLength(0);
  });

  test('CH-14: match subject 변수 → 사용된 것으로 처리', () => {
    const diags = check(`@mode(v)
fn main() -> i64 {
  let x = 3
  match x {
    case 1 => { return 1 }
    case _ => { return 0 }
  }
  return 0
}
`);
    expect(warns(diags)).toHaveLength(0);
  });

  test('CH-15: 함수 인자로 전달된 변수 → 사용된 것으로 처리', () => {
    const diags = check(`@mode(v)
fn double(n: i64) -> i64 {
  return n * 2
}
fn main() -> i64 {
  let v = 5
  let r = double(v)
  println(r)
  return 0
}
`);
    expect(diags).toHaveLength(0);
  });

});

