export interface WasmRunResult {
  /** 실행 성공 여부 */
  success: boolean;
  /** export 함수 호출 결과 (성공 시) */
  result?: unknown;
  /** 에러 메시지 (실패 시) */
  error?: string;
  /** 생성된 WAT 텍스트 (디버깅용) */
  wat?: string;
  /** 경고 목록 */
  warnings: string[];
}

export interface WasmModuleResult {
  /** 실행 성공 여부 */
  success: boolean;
  /** WebAssembly Instance (성공 시) */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  instance?: any;
  /** export 함수 이름 목록 */
  exports: string[];
  /** 생성된 WAT 텍스트 */
  wat: string;
  /** 경고 목록 */
  warnings: string[];
  /** 에러 메시지 (실패 시) */
