async compileModule(source: string): Promise<WasmModuleResult> {
  // 1. WAT 생성
  let watResult: ReturnType<NexusWasmRunner['generateWat']>;
  try {
    watResult = this.generateWat(source);
  } catch (e: any) {
    return {
      success: false,
      exports: [],
      wat: '',
      warnings: [],
      error: `WAT 생성 실패: ${e?.message ?? e}`,
    };
  }

  // 2. WASM 변환
  let wasm: Uint8Array;
  try {
    wasm = await this.watToWasm(watResult.wat);
  } catch (e: any) {
    return {
      success: false,
      exports: watResult.exports,
      wat: watResult.wat,
      warnings: watResult.warnings,
      error: `WAT→WASM 변환 실패: ${e?.message ?? e}`,
    };
  }

  // 3. WebAssembly 인스턴스화 (globalThis.WebAssembly — Node.js 내장)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const WA: any = (globalThis as any).WebAssembly;
  let instance: any;
  try {
    const mod = await WA.instantiate(wasm);
    instance = mod.instance;
  } catch (e: any) {
    return {
      success: false,
      exports: watResult.exports,
      wat: watResult.wat,
      warnings: watResult.warnings,
      error: `WASM 인스턴스화 실패: ${e?.message ?? e}`,
    };
  }

  return {
    success: true,
    instance,
    exports: watResult.exports,
    wat: watResult.wat,
    warnings: watResult.warnings,
  };
}

// ─── export 함수 호출 ────────────────────────────────────────────────────────

/**
 * 컴파일된 모듈에서 특정 export 함수 호출
